/* Domain 4.0 — course-aligned gap questions (organized by course section). Original wording. */

QS("4.1", "Secure Baselines", [
  ["How do you confirm that systems still match their secure baseline?",
    ["Run integrity measurements often and fix failures immediately", "Check at installation, then rely on change tickets", "Survey users quarterly about configuration changes", "Wait for the annual audit to report any drift"], 0,
    "Baselines define firewall settings, patch levels, and OS file versions. Integrity measurements compare systems against the documented baseline."],
  ["Where do organizations commonly get security baselines?",
    ["From the app developer, OS maker, or appliance manufacturer", "From the organization's cyber insurance provider", "From the most recent penetration test report", "From the CVE database maintained by MITRE"], 0,
    "Manufacturers often publish baselines. Windows alone has thousands of Group Policy settings, and only some relate to security."],
  ["Why must baselines be tested and measured when maintaining them?",
    ["Some baselines may contradict others in complex environments", "Baselines expire automatically unless they're re-tested", "Testing is required before baselines can be documented", "Untested baselines can't be pushed through Group Policy"], 0,
    "Best practices rarely change, but new vulnerabilities, applications, and OSes require updates, and baselines can conflict."],
  ["What's the key to deploying baselines to hundreds or thousands of devices?",
    ["Automation with central tools like Group Policy or MDM", "Manually configuring each device from a checklist", "Emailing step-by-step instructions to each user", "Having each department apply its own baseline"], 0,
    "Deployment usually happens from a centrally administered console, sometimes with several mechanisms."],
]);

QS("4.1", "Hardening Targets", [
  ["Which hardening steps apply to an RTOS device?",
    ["Isolate it, run minimal services, and use secure communication", "Install standard desktop antivirus and allow web browsing", "Give it remote internet access for vendor support", "Run every available service so it's always responsive"], 0,
    "RTOS devices in industrial, automotive, and military environments can't tolerate delays, so limit access and services."],
  ["What's the recommended way to segment IoT devices?",
    ["Put IoT devices on their own VLAN", "Put them on the same VLAN as domain controllers", "Connect them directly to the internet without a firewall", "Give them static public IPs"], 0,
    "Also change default passwords and deploy updates quickly. Weak defaults are a known IoT problem."],
  ["Which method is MOST efficient for keeping workstations patched?",
    ["Automate monthly patches through a policy system like Group Policy", "Let each user install updates when it's convenient for them", "Patch workstations only after a related breach is reported", "Delay updates for a year to avoid compatibility problems"], 0,
    "Workstation hardening: automate patches, use centralized policy, and remove unnecessary software to limit threats."],
  ["Why can embedded devices be harder to harden than watches or TVs?",
    ["Many can't be easily upgraded, so segmentation and firewalls help", "They auto-update from the vendor, so nothing else is needed", "They lack network connectivity, so hardening is unnecessary", "They run full desktop OSes that need endpoint agents"], 0,
    "Correct vulnerabilities with patches when possible, and segment and firewall to block unauthorized users."],
]);

QS("4.1", "Securing Wireless and Mobile", [
  ["What does a wireless heat map show?",
    ["Wireless signal strengths across an area", "CPU temperatures of access points", "Where users sit most often", "The number of malware infections"], 0,
    "Site surveys sample the spectrum, identify existing APs (you may not control all of them), plan around interference, and should be repeated as things change. Tools include built-in utilities, third-party tools, and spectrum analyzers."],
  ["What does CYOD mean?",
    ["Choose Your Own Device: like COPE, but the user picks it", "Configure Your Own Device: users manage their own settings", "Connect Your Own Device: personal devices on guest Wi-Fi", "Corporate Yearly Device: company replaces devices annually"], 0,
    "In COPE, the company owns the device and keeps full control (data can be deleted at any time). CYOD adds user choice."],
  ["Which is a key BYOD challenge?",
    ["It's both a home and work device, so data protection and resale are hard", "The company owns the hardware but not the data on it", "BYOD devices can't run the company's required apps", "BYOD devices can't be enrolled in any MDM system"], 0,
    "The employee owns the device but it must meet company requirements. MDM can manage the entire device or just a partition."],
  ["Which security concerns are specific to CELLULAR networks?",
    ["Traffic monitoring, location tracking, and worldwide access", "Bluetooth pairing attacks within a few meters", "Brute forcing the Wi-Fi pre-shared key", "Malware spread through USB charging ports"], 0,
    "Cellular networks divide land into cells with antennas. They raise privacy and monitoring concerns."],
  ["Bluetooth is best described as:",
    ["Short-range wireless that forms a personal area network (PAN)", "Long-range cellular that connects phones to towers", "A wireless LAN standard that replaces Wi-Fi", "A near-field standard that works only by touch"], 0,
    "Bluetooth connects phones, headsets, health monitors, cars, smartwatches, and enables tethering."],
  ["Which MDM capability helps secure single-user mobile devices?",
    ["Forcing screen locks and PINs", "Disabling all apps permanently", "Removing the device's encryption", "Allowing any app source"], 0,
    "MDM centrally sets policies on apps, data, and camera, controls the device or a partition, and manages access control."],
]);

QS("4.1", "Wireless Security Settings", [
  ["Why is a captured WPA2-PSK handshake dangerous?",
    ["They can brute force the PSK offline, and there's no forward secrecy", "It reveals each client's MAC address to the attacker", "It disconnects every client until the AP reboots", "It lets the attacker bypass 802.1X authentication"], 0,
    "Weak PSKs, fast GPUs, and cloud cracking make it easier. With the PSK, an attacker has everyone's wireless key."],
  ["Which block cipher mode does WPA3 use for stronger encryption than WPA2?",
    ["GCMP", "TKIP", "CCMP", "WEP"], 0,
    "GCMP provides confidentiality with AES and integrity with GMAC (Galois Message Authentication Code)."],
  ["How does SAE in WPA3 improve on WPA2-PSK?",
    ["Mutual authentication and a unique session key per user, with nothing to brute force", "It removes the PSK and requires RADIUS for every home network", "It keeps the four-way handshake but uses a longer hash", "It encrypts the PSK with RC4 before it's sent to the AP"], 0,
    "Simultaneous Authentication of Equals (the IEEE 'dragonfly' handshake) is a Diffie-Hellman-derived key exchange with authentication. The key never crosses the network."],
  ["In WPA3-Personal, what do all users share?",
    ["The same 256-bit pre-shared key", "Individual RADIUS credentials", "A unique certificate per user", "No authentication at all"], 0,
    "Open System needs no password, Personal/PSK uses one shared key, and Enterprise/802.1X authenticates each user individually against an authentication server."],
  ["Which devices commonly use RADIUS for centralized authentication?",
    ["Routers, switches, firewalls, servers, VPN access, and 802.1X", "Dial-up modems used for legacy remote access", "Printers and copiers on the local network", "Linux desktops using local accounts"], 0,
    "RADIUS is one of the most common AAA protocols and is available on almost any server OS. It's not just for dial-in anymore."],
  ["Which wireless security goal is supported by a message integrity check (MIC)?",
    ["Integrity", "Confidentiality", "Availability", "Authentication"], 0,
    "A secure wireless network authenticates users, encrypts data for confidentiality, and verifies integrity."],
]);

QS("4.1", "Application Security", [
  ["Checking all input and correcting improperly formatted data before processing is called:",
    ["Normalization", "Tokenization", "Sanitization", "Obfuscation"], 0,
    "Document every input method (forms, fields, type), validate actual vs expected, and fix improper data. Fuzzers will find what you missed."],
  ["What types of flaws do static code analyzers (SAST) have trouble identifying?",
    ["Authentication and cryptography weaknesses", "Buffer overflow conditions", "SQL injection points", "Hard-coded credentials"], 0,
    "SAST finds many issues easily, but not everything. Don't rely only on automation, and verify each finding since false positives occur."],
  ["In code signing, who signs the developer's public key, and what does the developer sign with?",
    ["A CA signs the developer's public key; the developer signs with their private key", "The developer signs the CA's key; the CA signs the code with its private key", "The user signs the code; the developer signs the user's certificate", "A CA signs the code; the developer signs the CA's certificate"], 0,
    "That lets users confirm who wrote the app and that it wasn't modified. For internal apps, use your own CA."],
  ["Which of these are examples of sandboxing?",
    ["VMs, mobile app isolation, browser iframes, and UAC", "RAID arrays, UPS units, and generators", "SPF, DKIM, and DMARC records", "VLAN trunking, STP, and port security"], 0,
    "Sandboxed applications can't access unrelated resources. It's common during development and useful in production."],
  ["Should sensitive information be stored in a cookie?",
    ["No, cookies aren't designed to be secure storage", "Yes, as long as the Secure attribute is set", "Yes, because browsers encrypt cookies by default", "Yes, if the HttpOnly attribute is also set"], 0,
    "The Secure attribute only ensures HTTPS transmission. Cookies still sit on the user's computer."],
  ["What can application security monitoring reveal?",
    ["Blocked SQLi attempts, unusual file transfers, and spikes in access", "The source code changes made by each developer", "The app's code-signing certificate expiration date", "The number of bugs found during QA testing"], 0,
    "Real-time monitoring and log audits reveal usage, blocked attacks, information gathering, and anomalies."],
]);

QS("4.2", "Asset Management", [
  ["What's typically the FIRST step in the acquisition/procurement process?",
    ["A user request with budget info and approvals", "Payment to the selected supplier", "Negotiating terms with suppliers", "Tagging the asset in inventory"], 0,
    "Procurement flows from request to negotiation with suppliers to purchase, invoice, and payment."],
  ["Hardware and software assets are often classified by expense type. Which pairing is typical?",
    ["Hardware is capital expense; software is operating expense", "Both hardware and software are capital expenses", "Software is capital expense; hardware is operating expense", "Both hardware and software are operating expenses"], 0,
    "Assignment and accounting involves a central tracking system, ownership (associating a person with an asset), and classification."],
  ["Listing all the parts of an asset (CPU, memory, storage, keyboard, mouse) is called:",
    ["Enumeration", "Sanitization", "Attestation", "Provisioning"], 0,
    "Monitoring and tracking include inventorying every asset, associating tickets with make and model, enumeration, and asset tags (barcode, RFID, tracking number)."],
  ["Which is TRUE about properly sanitized media?",
    ["It's one-way: no usable data remains, even with forensic tools", "Data can still be recovered with specialized forensic software", "It removes file names but leaves the file contents intact", "It requires the drive to be physically destroyed afterward"], 0,
    "Sanitization can clean an entire drive for reuse or permanently delete a single file."],
  ["Which physical destruction method is described as 'quick and easy' for hard drives?",
    ["Drilling through the platters", "Industrial shredding", "Incineration", "Degaussing"], 0,
    "Options: shredders and pulverizers (heavy machinery), drills and hammers (quick), degaussing (removes the magnetic field and ruins the drive), and incineration."],
  ["Why do organizations keep data beyond what's needed day to day?",
    ["Regulatory compliance and needs like accidental deletion and DR", "To reduce storage costs by keeping data in one location", "Because deleting any business data is prohibited by law", "To give attackers less reason to target the backups"], 0,
    "Data retention covers how much to keep, where, versions, lifecycle, and purging. Differentiate by data type and application."],
]);

QS("4.3", "Vulnerability Scanning", [
  ["Why should vulnerability scans be run from BOTH outside and inside the network?",
    ["To see what outsiders see without ignoring insider threats", "Because internal scans are faster than external scans", "Because external scans can't detect open ports", "Because scanners need two passes to build signatures"], 0,
    "Scans are minimally invasive (unlike pen tests): port scans, system and security device identification, and gathering as much information as possible."],
  ["Fault-injecting, robustness testing, syntax testing, and negative testing are other names for:",
    ["Fuzzing", "Static analysis", "Code review", "Package monitoring"], 0,
    "Fuzzing sends random input looking for crashes, server errors, and exceptions. It began as a 1988 University of Wisconsin class project."],
  ["Which framework from Carnegie Mellon's CERT is an example of a fuzzing tool?",
    ["Basic Fuzzing Framework (BFF)", "MITRE ATT&CK framework", "CIS Critical Security Controls", "NIST Cybersecurity Framework"], 0,
    "Fuzzing engines are platform- or language-specific and processor-intensive, so many use high-probability tests."],
  ["What does package monitoring help confirm before deploying open-source packages?",
    ["It's legitimate: trusted source, no malware, no embedded vulnerabilities", "It's the newest available version of the package", "It has the most downloads in the package repository", "It's written in a memory-safe programming language"], 0,
    "Package monitoring addresses supply chain integrity. Verify the contents before deployment."],
]);

